def _public_use_case(function: Any) -> Any:
    """Translate internal module errors into one application error contract."""

    parameters = list(signature(function).parameters)
    item_position = parameters.index("work_item_id") if "work_item_id" in parameters else None

    @wraps(function)
    def wrapped(*args: Any, **kwargs: Any) -> Any:
        try:
            configured_scope = ProjectContextResolver(args[0].project).operation(args[0].project_bindings) if args and hasattr(args[0], "project") else nullcontext()
            with configured_scope:
                if args and hasattr(args[0], "project"):
                    if function.__name__ not in {
                        "project_current_action", "inspect_implementation_alignment",
                        "cancel", "cancel_planned_delivery_activity", "request_replan",
                    }:
                        identifier = kwargs.get("work_item_id")
                        if identifier is None and item_position is not None and item_position < len(args):
                            identifier = args[item_position]
                        args[0]._prepare_project_use_case(function.__name__, identifier)
                    scope = project_operation(args[0].management_project, operation_name=function.__name__)
                else:
                    scope = nullcontext()
                with scope:
                    if args and item_position is not None:
                        arguments = signature(function).bind_partial(*args, **kwargs).arguments
                        with args[0]._repository_operation_for(function.__name__, arguments):
                            effect_lock = args[0]._effect_lock(arguments["work_item_id"], "verification") if function.__name__ == "verify" else nullcontext()
                            with effect_lock:
                                return function(*args, **kwargs)
                    return function(*args, **kwargs)
        except ApplicationCoordinatorError:
            raise
        except (
            WorkflowAuthorityError,
            MaintenanceError,
            EvidenceReferenceError,
            EngineeringGovernanceError,
            GitWorkspaceError,
            GitProjectReaderError,
            ProjectContextError,
            VerificationRunnerError,
            ActualResultError,
            DeliveryActivityError,
            AgentSetupError,
            ProjectAuthorityConsistencyError,
            ProjectEngineeringBaselineError,
            ProjectAuthorityDecisionError,
            ProjectImplementationAlignmentError,
            ImplementationAlignmentPreparationError,
            YamlMetadataPatchError,
            OSError,
        ) as error:
            error_codes = {
                GitProjectReaderError: "project_read_failed",
                ProjectImplementationAlignmentError: (
                    "project_implementation_alignment_invalid"
                ),
                YamlMetadataPatchError: "project_metadata_patch_failed",
                OSError: "project_io_failed",
            }
            default_code = next(
                (
                    code
                    for error_type, code in error_codes.items()
                    if isinstance(error, error_type)
                ),
                "application_use_case_rejected",
            )
            raise ApplicationCoordinatorError(
                getattr(error, "code", default_code),
                str(error),
                details=(
                    getattr(error, "issues", None)
                    or getattr(error, "details", None)
                ),
            ) from error

    return wrapped

@_public_use_case
def confirm_project_authorities(
    self,
    work_item_id: str,
    payload: Mapping[str, Any],
    *,
    expected_version: int,
) -> dict[str, Any]:
    """Atomically apply one complete, separately presented decision package."""

    with self._effect_lock(work_item_id, "project_authority_confirmation"):
        return self._confirm_project_authorities_locked(
            work_item_id,
            payload,
            expected_version=expected_version,
        )

def _confirm_project_authorities_locked(
    self,
    work_item_id: str,
    payload: Mapping[str, Any],
    *,
    expected_version: int,
) -> dict[str, Any]:
    """Run one complete authority transaction while holding its host lock."""

    current = self._current_for_effect(
        work_item_id,
        expected_version,
        {"implementing"},
    )
    self._require_current_work_item_direction_context(current)
    binding = self._verification_work_area(current)
    worktree = str(binding["worktree_path"])
    action = current.get("current_action")
    if not isinstance(action, Mapping):
        action = current_action_for(current)
    if (
        not isinstance(action, Mapping)
        or action.get("action_type")
        != "confirm_project_authority_candidates"
    ):
        raise ApplicationCoordinatorError(
            "project_authority_action_not_current",
            "只能确认当前动作中已完整独立展示的长期权威候选包",
        )
    presentations = current_project_authority_presentations(current)
    candidate_review = current_project_authority_review(current)
    current_bundle = project_authority_review_bundle(
        worktree,
        current,
        presentations,
    )
    recorded_bundle = candidate_review.get("candidate_bundle")
    if (
        not isinstance(recorded_bundle, Mapping)
        or dict(recorded_bundle) != dict(current_bundle)
    ):
        raise ApplicationCoordinatorError(
            "project_authority_review_stale",
            "八视角复核之后候选正文发生变化；必须先重新复核当前完整候选包",
            details={
                "recorded_bundle_sha256": (
                    recorded_bundle.get("content_sha256")
                    if isinstance(recorded_bundle, Mapping)
                    else None
                ),
                "current_bundle_sha256": current_bundle["content_sha256"],
            },
        )
    raw_decisions = payload.get("decisions")
    if set(payload) != {"decisions"} or not isinstance(raw_decisions, list):
        raise ApplicationCoordinatorError(
            "project_authority_confirmation_bundle_invalid",
            "长期权威确认必须且只能提交完整 decisions（决定）数组",
        )
    expected_kinds = [
        str(presentation["authority_kind"])
        for presentation in presentations
    ]
    submitted_kinds = [
        str(value.get("authority_kind") or "")
        if isinstance(value, Mapping)
        else ""
        for value in raw_decisions
    ]
    if submitted_kinds != expected_kinds:
        raise ApplicationCoordinatorError(
            "project_authority_confirmation_bundle_invalid",
            "长期权威确认包必须按展示顺序完整覆盖当前全部候选",
            details={
                "expected_authority_kinds": expected_kinds,
                "submitted_authority_kinds": submitted_kinds,
            },
        )
    confirmations: list[dict[str, Any]] = []
    for index, (presentation, raw) in enumerate(
        zip(presentations, raw_decisions, strict=True)
    ):
        assert isinstance(raw, Mapping)
        if set(raw) != {
            "authority_kind",
            "candidate_fingerprint",
            "user_confirmation",
            "agent_decision",
        }:
            raise ApplicationCoordinatorError(
                "project_authority_confirmation_bundle_invalid",
                f"decisions[{index}] 字段不完整或包含未知字段",
            )
        try:
            confirmations.append(
                confirmation_record_from_input(
                    presentation["confirmation_challenge"],
                    {
                        "candidate_fingerprint": raw.get(
                            "candidate_fingerprint"
                        ),
                        "user_confirmation": raw.get(
                            "user_confirmation"
                        ),
                        "agent_decision": raw.get("agent_decision"),
                    },
                )
            )
        except ConfirmationProtocolError as error:
            raise ApplicationCoordinatorError(
                error.code,
                str(error),
                details={"decision_index": index},
            ) from error
    accepted_by_kind = {
        kind: confirmation["accepted"] is True
        for kind, confirmation in zip(
            expected_kinds,
            confirmations,
            strict=True,
        )
    }
    invalid_acceptances = {
        kind: [
            prerequisite
            for prerequisite in project_authority_prerequisites(kind)
            if prerequisite in accepted_by_kind
            and accepted_by_kind[prerequisite] is False
        ]
        for kind in expected_kinds
        if accepted_by_kind[kind]
    }
    invalid_acceptances = {
        kind: prerequisites
        for kind, prerequisites in invalid_acceptances.items()
        if prerequisites
    }
    if invalid_acceptances:
        raise ApplicationCoordinatorError(
            "project_authority_confirmation_order_invalid",
            "被接受的下游候选不能依赖同一确认包中已退回的上游候选",
            details=invalid_acceptances,
        )
    self._require_authority_confirmation_path_scope(
        current,
        project_dir=worktree,
    )
    pending_effect = current.get("data", {}).get("pending_effect")
    recovering_confirmation = bool(
        isinstance(pending_effect, Mapping)
        and pending_effect.get("kind")
        == "project_authority_confirmation"
    )
    if not recovering_confirmation:
        for presentation in presentations:
            authority_kind = str(presentation["authority_kind"])
            current_candidate = project_authority_candidate(
                worktree,
                current,
                authority_kind,
            )
            if dict(current_candidate) != dict(presentation["candidate"]):
                raise ApplicationCoordinatorError(
                    "project_authority_candidate_changed",
                    "候选展示之后长期权威正文或上游绑定发生变化；请重新展示候选包",
                    details={"authority_kind": authority_kind},
                )
    intent_base = {
        "decisions": deepcopy(list(raw_decisions)),
        "candidate_fingerprints": [
            str(
                presentation["confirmation_challenge"].get(
                    "candidate_fingerprint"
                )
                or ""
            )
            for presentation in presentations
        ],
    }
    transaction_decisions = [
        {
            "candidate": deepcopy(dict(presentation["candidate"])),
            "accepted": confirmation["accepted"] is True,
        }
        for presentation, confirmation in zip(
            presentations,
            confirmations,
            strict=True,
        )
    ]
    if recovering_confirmation:
        assert isinstance(pending_effect, Mapping)
        stored_intent = pending_effect.get("intent")
        if not isinstance(stored_intent, Mapping):
            raise WorkflowAuthorityError(
                "external_effect_intent_invalid",
                "长期权威确认恢复意图结构无效",
            )
        confirmed_at = str(stored_intent.get("confirmed_at") or "")
        if any(
            stored_intent.get(field) != value
            for field, value in intent_base.items()
        ):
            raise WorkflowAuthorityError(
                "external_effect_intent_changed",
                "待恢复长期权威确认与当前完整决定包不一致",
            )
        metadata_transaction = stored_intent.get("metadata_transaction")
        if not isinstance(metadata_transaction, Mapping):
            raise WorkflowAuthorityError(
                "external_effect_intent_invalid",
                "长期权威确认恢复意图缺少精确元数据事务",
            )
        confirmation_intent = deepcopy(dict(stored_intent))
    else:
        confirmed_at = datetime.now(timezone.utc).isoformat().replace(
            "+00:00", "Z"
        )
        metadata_transaction = (
            build_project_authority_confirmation_transaction(
                worktree,
                current,
                transaction_decisions,
                confirmed_on=confirmed_at[:10],
            )
        )
        confirmation_intent = {
            **intent_base,
            "confirmed_at": confirmed_at,
            "metadata_transaction": metadata_transaction,
        }
    current = self._claim_external_effect(
        current,
        kind="project_authority_confirmation",
        intent=confirmation_intent,
    )
    records: list[dict[str, Any]] = []
    originals: dict[Path, bytes] = {}
    working_item = deepcopy(dict(current))
    working_data = deepcopy(dict(working_item.get("data") or {}))
    working_item["data"] = working_data
    working_records = list(
        working_data.get("project_authority_decisions") or []
    )
    try:
        changed_originals = (
            apply_project_authority_confirmation_transaction(
                worktree,
                metadata_transaction,
            )
        )
        originals.update(changed_originals)
        for presentation, confirmation in zip(
            presentations,
            confirmations,
            strict=True,
        ):
            authority_kind = str(presentation["authority_kind"])
            candidate = presentation["candidate"]
            if confirmation["accepted"] is True:
                confirmed = confirmed_project_authority_snapshot(
                    worktree,
                    working_item,
                    candidate,
                )
                current_candidate = dict(candidate)
            else:
                current_candidate = project_authority_candidate(
                    worktree,
                    working_item,
                    authority_kind,
                )
            if dict(current_candidate) != dict(candidate):
                raise ApplicationCoordinatorError(
                    "project_authority_candidate_changed",
                    "候选展示之后长期权威正文或上游绑定发生变化；请重新展示候选包",
                    details={"authority_kind": authority_kind},
                )
            record: dict[str, Any] = {
                "schema_version": PROJECT_AUTHORITY_DECISION_SCHEMA,
                "authority_kind": authority_kind,
                "candidate": deepcopy(dict(candidate)),
                "confirmation_challenge": deepcopy(
                    dict(presentation["confirmation_challenge"])
                ),
                "confirmation": confirmation,
                "confirmed_at": confirmed_at,
                "confirmed_on": None,
                "confirmed_content_sha256": None,
                "semantic_content_machine_proven": False,
            }
            if confirmation["accepted"] is True:
                record["confirmed_on"] = confirmed["confirmed_on"]
                record["confirmed_content_sha256"] = confirmed[
                    "confirmed_content_sha256"
                ]
            working_records.append(record)
            working_data["project_authority_decisions"] = working_records
            records.append(record)
        return self.authority.transition(
            work_item_id,
            "record_project_authority_decision_bundle",
            {"project_authority_decisions": records},
            expected_version=int(current["version"]),
        )
    except Exception:
        restore_yaml_patch_originals(worktree, metadata_transaction, originals)
        raise

class ImplementationAlignmentArtifactStore:
    """Store small manifests and reusable, bounded JSON component pages."""

    _ROOT = PurePosixPath(".strixnova/artifacts/implementation-alignment")
    _PREPARATION_COMPONENT_FIELDS = (
        "baseline",
        "domain_model",
        "architecture_model",
        "architecture",
        "documents",
        "governed_hashes",
        "observation",
        "decision_catalog",
    )
    _CAPTURE_COMPONENT_FIELDS = ("observation",)

    def __init__(self, project: Path) -> None:
        self.project = project.resolve()
        self.root = self.project.joinpath(*self._ROOT.parts)

    def _write_content(self, directory: str, content: bytes) -> tuple[Path, str]:
        digest = hashlib.sha256(content).hexdigest()
        target = self.root / directory / f"{digest}.json"
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists():
            if target.read_bytes() != content:
                raise AlignmentArtifactError(
                    "alignment_artifact_hash_collision",
                    "内容寻址实现对齐产物发生散列冲突",
                )
            return target, digest
        with tempfile.NamedTemporaryFile(
            mode="wb",
            prefix=f".{target.name}.",
            suffix=".next",
            dir=target.parent,
            delete=False,
        ) as stream:
            stream.write(content)
            stream.flush()
            os.fsync(stream.fileno())
            temporary = Path(stream.name)
        try:
            os.replace(temporary, target)
            _fsync_directory(target.parent)
        finally:
            temporary.unlink(missing_ok=True)
        return target, digest

    def _component_ref(self, payload: Mapping[str, Any]) -> dict[str, str]:
        content = _canonical_json(payload)
        if len(content) > MAX_CHUNK_BYTES:
            raise AlignmentArtifactError(
                "alignment_component_too_large",
                "实现对齐组件单页超过 8 MiB；必须继续分块",
                details={"size_bytes": len(content)},
            )
        target, digest = self._write_content("components", content)
        return {
            "schema_version": COMPONENT_REF_SCHEMA,
            "artifact_id": "ALIGNCOMP-" + digest[:16].upper(),
            "path": target.relative_to(self.project).as_posix(),
            "content_sha256": digest,
        }

    @staticmethod
    def _value_payload(value: Any) -> dict[str, Any]:
        return {"schema_version": CHUNK_SCHEMA, "kind": "value", "value": value}

    def _store_value(self, value: Any) -> dict[str, str]:
        direct = self._value_payload(value)
        content = _canonical_json(direct)
        if len(content) <= PAGE_TARGET_BYTES or not isinstance(
            value, (list, dict)
        ):
            return self._component_ref(direct)
        if isinstance(value, list):
            segments: list[dict[str, Any]] = []
            page: list[Any] = []
            for item in value:
                candidate = [*page, item]
                candidate_size = len(_canonical_json(self._value_payload(candidate)))
                if page and (
                    len(page) >= MAX_PAGE_ITEMS
                    or candidate_size > PAGE_TARGET_BYTES
                ):
                    segments.append(
                        {"kind": "page", "ref": self._component_ref(self._value_payload(page))}
                    )
                    page = []
                    candidate = [item]
                    candidate_size = len(
                        _canonical_json(self._value_payload(candidate))
                    )
                if candidate_size > PAGE_TARGET_BYTES:
                    if page:
                        segments.append(
                            {"kind": "page", "ref": self._component_ref(self._value_payload(page))}
                        )
                        page = []
                    segments.append({"kind": "item", "ref": self._store_value(item)})
                else:
                    page = candidate
            if page:
                segments.append(
                    {"kind": "page", "ref": self._component_ref(self._value_payload(page))}
                )
            return self._component_ref(
                {
                    "schema_version": CHUNK_SCHEMA,
                    "kind": "list_segments",
                    "item_count": len(value),
                    "segments": segments,
                }
            )

        pages: list[dict[str, str]] = []
        separate_entries: list[dict[str, Any]] = []
        page_map: dict[str, Any] = {}
        for key in sorted(value, key=str):
            text_key = str(key)
            candidate = {**page_map, text_key: value[key]}
            candidate_size = len(_canonical_json(self._value_payload(candidate)))
            if page_map and (
                len(page_map) >= MAX_PAGE_ITEMS
                or candidate_size > PAGE_TARGET_BYTES
            ):
                pages.append(self._component_ref(self._value_payload(page_map)))
                page_map = {}
                candidate = {text_key: value[key]}
                candidate_size = len(_canonical_json(self._value_payload(candidate)))
            if candidate_size > PAGE_TARGET_BYTES:
                if page_map:
                    pages.append(self._component_ref(self._value_payload(page_map)))
                    page_map = {}
                separate_entries.append(
                    {"key": text_key, "value_ref": self._store_value(value[key])}
                )
            else:
                page_map = candidate
        if page_map:
            pages.append(self._component_ref(self._value_payload(page_map)))
        return self._component_ref(
            {
                "schema_version": CHUNK_SCHEMA,
                "kind": "map_pages",
                "entry_count": len(value),
                "pages": pages,
                "separate_entries": separate_entries,
            }
        )

def write_candidate(
    self,
    current: Mapping[str, Any],
    payload: Mapping[str, Any],
    *,
    current_binding_check: Callable[[], Mapping[str, Any]] | None = None,
) -> dict[str, Any]:
    if not isinstance(payload, Mapping) or set(payload) != {
        "schema_version",
        "preparation_ref",
        "decisions",
        "deviations",
        "unresolved_items",
    }:
        raise ImplementationAlignmentPreparationError(
            "alignment_decisions_invalid",
            "实现对齐候选输入字段不完整或包含未知字段",
        )
    binding = self._binding(current)
    implementation_root = Path(str(binding["implementation_root"]))
    self._recover_transactions(implementation_root, [Path(path) for path in binding["allowed_targets"]])
    preparation_ref = payload.get("preparation_ref")
    if not isinstance(preparation_ref, Mapping):
        raise ImplementationAlignmentPreparationError(
            "alignment_preparation_ref_invalid",
            "实现对齐候选缺少准备引用",
        )
    packet = self._load_preparation(preparation_ref)
    self._assert_current_binding(packet, binding)
    self._assert_target_file_bindings(
        packet,
        implementation_root,
    )
    documents = packet.get("documents")
    if not isinstance(documents, Mapping):
        raise ImplementationAlignmentPreparationError(
            "alignment_preparation_invalid",
            "实现对齐准备包缺少现有底账",
        )
    catalog = self._expanded_decision_catalog(
        documents,
        packet.get("decision_catalog"),
    )
    decisions, catalog_by_ref = self._decision_values(catalog, payload)
    raw_deviations = payload.get("deviations")
    unresolved_items = payload.get("unresolved_items")
    if not isinstance(raw_deviations, list) or not isinstance(
        unresolved_items, list
    ):
        raise ImplementationAlignmentPreparationError(
            "alignment_decisions_invalid",
            "deviations 和 unresolved_items 必须是数组",
        )

    project = implementation_root
    hashes = {
        str(path): str(digest)
        for path, digest in packet["governed_hashes"].items()
    }
    observation = packet["observation"]
    architecture = packet["architecture"]

    source_records: list[dict[str, Any]] = []
    for reference, item in catalog_by_ref.items():
        if item.get("kind") != "source_record":
            continue
        facts = item["facts"]
        value = decisions.get(reference)
        previous = facts.get("previous")
        semantic = value if value is not None else previous
        if not isinstance(semantic, Mapping):
            raise ImplementationAlignmentPreparationError(
                "alignment_decisions_incomplete",
                f"源码记录缺少语义决定：{reference}",
            )
        source_records.append(
            {
                "scope_id": str(facts["scope_id"]),
                "path": str(facts["path"]),
                "sha256": str(facts["sha256"]),
                "repository_id": facts["repository_id"],
                **{
                    field: deepcopy(semantic.get(field))
                    for field in item["required_value_fields"]
                },
            }
        )
    source_current = {
        "governed_source_scopes": deepcopy(
            documents["source"]["governed_source_scopes"]
        ),
        "records": source_records,
    }
    try:
        repository_readers = self._repository_inputs(current, ProjectEngineeringBaseline(project))
        source_records, governed_hashes = _ownership(project, source_current, repository_readers)
    except ValueError as error:
        raise ImplementationAlignmentPreparationError(
            "alignment_source_decisions_invalid",
            str(error),
        ) from error
    if governed_hashes != hashes:
        raise ImplementationAlignmentPreparationError(
            "alignment_preparation_stale",
            "受管源码字节或文件集合已变化；请重新 prepare",
        )

    dependency_records: list[dict[str, Any]] = []
    for reference, item in catalog_by_ref.items():
        if item.get("kind") != "dependency_record":
            continue
        facts = item["facts"]
        value = decisions.get(reference)
        previous = facts.get("previous")
        semantic = value if value is not None else previous
        if not isinstance(semantic, Mapping):
            raise ImplementationAlignmentPreparationError(
                "alignment_decisions_incomplete",
                f"依赖记录缺少语义决定：{reference}",
            )
        dependency_records.append(
            {
                **{
                    str(key): deepcopy(value)
                    for key, value in facts.items()
                    if key != "previous"
                },
                **{
                    field: deepcopy(semantic.get(field))
                    for field in item["required_value_fields"]
                },
            }
        )
    try:
        dependencies = _dependencies(
            source_records,
            architecture,
            {"records": dependency_records},
            observation,
        )
    except ValueError as error:
        raise ImplementationAlignmentPreparationError(
            "alignment_dependency_decisions_invalid",
            str(error),
        ) from error

    responsibility_records: list[dict[str, Any]] = []
    for reference, item in catalog_by_ref.items():
        if item.get("kind") != "responsibility_record":
            continue
        facts = item["facts"]
        value = decisions.get(reference)
        previous = facts.get("previous")
        semantic = value if value is not None else previous
        if not isinstance(semantic, Mapping):
            raise ImplementationAlignmentPreparationError(
                "alignment_decisions_incomplete",
                f"目标责任缺少语义决定：{reference}",
            )
        responsibility_records.append(
            {
                "target_id": str(facts["target_id"]),
                **{
                    field: deepcopy(semantic.get(field))
                    for field in item["required_value_fields"]
                },
            }
        )
    try:
        responsibilities = _responsibilities(
            architecture,
            {"records": responsibility_records},
        )
    except ValueError as error:
        raise ImplementationAlignmentPreparationError(
            "alignment_responsibility_decisions_invalid",
            str(error),
        ) from error

    model = deepcopy(documents["model"])
    revision = model.get("revision")
    if not isinstance(revision, Mapping) or revision.get("status") != "draft":
        raise ImplementationAlignmentPreparationError(
            "alignment_revision_not_draft",
            "write-candidate 只能写入具有新修订身份的 draft 实现对齐",
        )
    revision_id = str(revision.get("revision_id") or "")
    domain_model = packet["domain_model"]
    architecture_model = packet["architecture_model"]
    head = _git(project, "rev-parse", "HEAD")
    worktree_state = "dirty" if _git(project, "status", "--porcelain") else "clean"
    model["domain_model_ref"] = {
        "model_id": domain_model["model_id"],
        "revision_id": domain_model["revision"]["revision_id"],
    }
    model["architecture_ref"] = {
        "architecture_id": architecture_model["architecture_id"],
        "revision_id": architecture_model["revision"]["revision_id"],
    }
    model["code_snapshot"] = {
        "repositories": deepcopy(packet["repository_content_refs"]),
        "governed_source_manifest_sha256": _manifest(governed_hashes),
        "observed_on": str(packet["observed_on"]),
    }
    model["observation_coverage"] = {
        "contract_version": observation["schema_version"],
        "overall_status": observation["overall_coverage_status"],
        "source_manifest_sha256": observation["source_manifest_sha256"],
        "observation_snapshot_sha256": observation[
            "observation_snapshot_sha256"
        ],
        "observed_paths": deepcopy(observation["observed_paths"]),
        "records": deepcopy(observation["coverage"]),
        "provider_receipts": deepcopy(observation["provider_receipts"]),
    }
    model["unresolved_items"] = deepcopy(unresolved_items)
    model.pop("semantic_content_machine_proven", None)

    model_id = str(model["alignment_model_id"])
    source_document = {
        "schema_version": "strixnova.implementation-source-ownership.v1",
        "alignment_model_id": model_id,
        "alignment_revision_id": revision_id,
        "governed_source_scopes": deepcopy(
            documents["source"]["governed_source_scopes"]
        ),
        "records": source_records,
    }
    dependencies_document = {
        "schema_version": "strixnova.implementation-actual-dependencies.v1",
        "alignment_model_id": model_id,
        "alignment_revision_id": revision_id,
        "observation_contract_version": observation["schema_version"],
        "records": dependencies,
    }
    responsibilities_document = {
        "schema_version": "strixnova.implementation-target-responsibilities.v1",
        "alignment_model_id": model_id,
        "alignment_revision_id": revision_id,
        "records": responsibilities,
    }
    deviations_document = {
        "schema_version": "strixnova.implementation-deviations.v1",
        "alignment_model_id": model_id,
        "alignment_revision_id": revision_id,
        "deviations": deepcopy(raw_deviations),
    }

    baseline = self._persistable(packet["baseline"])
    baseline["schema_version"] = "strixnova.project-engineering-baseline.v1"
    alignment_ref = baseline["authority_refs"]["implementation_alignment"]
    alignment_ref["revision_id"] = revision_id
    alignment_ref["status"] = {
        "revision_status": "draft",
        "adoption_status": "under_review",
    }
    baseline["code_version"] = {
        "repositories": deepcopy(packet["repository_content_refs"]),
    }
    reason = (
        "实现对齐候选已绑定当前代码观察；语义仍需 Agent 复核并由实际结果确认。"
    )
    baseline["review_state"] = {
        "required": True,
        "reasons": list(
            dict.fromkeys(
                [
                    *(baseline.get("review_state", {}).get("reasons") or []),
                    reason,
                ]
            )
        ),
        "affected_authority_kinds": sorted(
            {
                *(
                    baseline.get("review_state", {}).get(
                        "affected_authority_kinds"
                    )
                    or []
                ),
                "implementation_alignment",
                "code_version",
            }
        ),
    }

    paths = model["artifact_paths"]
    documents_to_write = [
        (project / str(binding["alignment_path"]), model),
        (project / str(paths["source_ownership"]), source_document),
        (project / str(paths["actual_dependencies"]), dependencies_document),
        (
            project / str(paths["target_responsibilities"]),
            responsibilities_document,
        ),
        (project / str(paths["deviations"]), deviations_document),
        (Path(packet.get("baseline_root", str(project))) / str(packet["baseline_path"]), baseline),
    ]

    # Recheck immediately before the transaction so a valid edit made
    # after prepare is rejected instead of being replaced by packet bytes.
    self._assert_target_file_bindings(packet, project)

    def validate_replaced() -> None:
        ProjectEngineeringBaseline(project).load(
            required=True,
            allow_candidate_refs=True,
        )
        baseline_reader = ProjectEngineeringBaseline(project)
        context = baseline_reader.context
        domain_ref = baseline["authority_refs"]["domain_model"]
        architecture_ref = baseline["authority_refs"]["target_architecture"]
        domain_source = context.authority_reader(domain_ref, parent_reader=baseline_reader.reader) if context is not None else baseline_reader.reader
        architecture_source = context.authority_reader(architecture_ref, parent_reader=baseline_reader.reader) if context is not None else baseline_reader.reader
        ProjectImplementationAlignment(
            project,
            str(binding["alignment_path"]),
            domain_model_path=str(
                baseline["authority_refs"]["domain_model"]["path"]
            ),
            architecture_description_path=str(
                baseline["authority_refs"]["target_architecture"]["path"]
            ),
            domain_reader=ProjectDomainModel(domain_source.project, domain_ref["path"], shared_reader=domain_source),
            architecture_reader=ProjectArchitectureDescription(architecture_source.project, architecture_ref["path"], shared_reader=architecture_source),
            repository_readers=repository_readers,
        ).load()
        if current_binding_check is not None:
            latest = current_binding_check()
            self._assert_current_binding(packet, self._binding(latest))

    try:
        _atomic_dump_many(
            documents_to_write,
            validate_replaced=validate_replaced,
            transaction_root=self._transaction_root(project),
            recovery_root=project,
            allowed_targets=[Path(path) for path in packet["target_file_locations"].values()],
        )
    except ImplementationAlignmentPreparationError:
        raise
    except (
        OSError,
        ValueError,
        DocumentTransactionError,
        ProjectImplementationAlignmentError,
    ) as error:
        raise ImplementationAlignmentPreparationError(
            "alignment_candidate_write_failed",
            "实现对齐候选没有通过恢复性写入和完整结构复核",
            details=getattr(error, "issues", [str(error)]),
        ) from error
    output_hashes = {
        target.relative_to(project).as_posix(): hashlib.sha256(
            target.read_bytes()
        ).hexdigest()
        for target, _value in documents_to_write
    }
    complete_alignment = bool(
        observation["overall_coverage_status"] == "complete"
        and not unresolved_items
        and not raw_deviations
        and all(
            record.get("disposition") != "owned"
            or record.get("current_status") == "aligned"
            for record in source_records
        )
        and all(
            record.get("classification")
            in PASSING_REFRESH_CLASSIFICATIONS
            for record in dependencies
        )
        and all(
            record.get("status") == "implemented"
            for record in responsibilities
        )
    )
    return {
        "schema_version": "strixnova.implementation-alignment-candidate-result.v1",
        "candidate_valid": True,
        "complete_alignment": complete_alignment,
        "alignment_model_id": model_id,
        "alignment_revision_id": revision_id,
        "candidate_status": "draft",
        "written_paths": sorted(output_hashes),
        "content_sha256_by_path": output_hashes,
        "observation_coverage_status": observation[
            "overall_coverage_status"
        ],
        "semantic_content_machine_proven": False,
    }

class ImplementationCandidateEvidence:
    """Own slice realization and accepted-delivery byte comparisons."""

    def __init__(self, project_dir: str | Path) -> None:
        self.project = Path(project_dir).resolve()

    @staticmethod
    def _work_area(current: Mapping[str, Any]) -> dict[str, Any]:
        data = current.get("data")
        value = data.get("git") if isinstance(data, Mapping) else None
        if not isinstance(value, Mapping) or value.get("schema_version") != (
            "strixnova.git-work-area.v1"
        ):
            raise WorkflowAuthorityError(
                "git_work_area_missing",
                "当前 WorkItem 没有有效的 Git 工作区记录",
            )
        return dict(value)

    @staticmethod
    def operation_refs(slice_value: Mapping[str, Any]) -> list[str]:
        return list(
            dict.fromkeys(
                [
                    *(slice_value.get("operation_refs") or []),
                    *(slice_value.get("continued_operation_refs") or []),
                ]
            )
        )

    @classmethod
    def operation_paths(
        cls,
        plan: Mapping[str, Any],
        slice_value: Mapping[str, Any],
        *, repository_id: Any = ...,
    ) -> list[str]:
        operations = list(plan.get("operations") or [])
        paths: set[str] = set()
        for reference in cls.operation_refs(slice_value):
            text = str(reference)
            if not text.startswith("operations[") or not text.endswith("]"):
                continue
            index_text = text[len("operations[") : -1]
            if not index_text.isdigit() or int(index_text) >= len(operations):
                continue
            operation = operations[int(index_text)]
            if not isinstance(operation, Mapping):
                continue
            if repository_id is not ... and operation.get("repository_id") != repository_id:
                continue
            for field in ("path", "to_path"):
                path = str(operation.get(field) or "").replace("\\", "/").strip()
                if path:
                    paths.add(path)
        return sorted(paths)

    def operation_realization(
        self,
        current: Mapping[str, Any],
        plan: Mapping[str, Any],
        slice_value: Mapping[str, Any],
        *,
        observed_ref: str | None = None,
    ) -> list[dict[str, Any]]:
        operations = list(plan.get("operations") or [])
        work_area = self._work_area(current)
        base_commit = str(work_area.get("base_commit") or "")
        selected_scope = next((entry for entry in (plan.get("repository_scope") or {}).get("repositories", []) if entry["repository_id"] == current["data"].get("selected_repository_id")), {})
        if selected_scope.get("investigation_ref") not in {None, "working_tree"}:
            base_commit = selected_scope["investigation_ref"]
        try:
            base_reader = GitProjectReader(self.project, observed_ref=base_commit)
            current_reader = GitProjectReader(
                self.project,
                observed_ref=observed_ref,
            )
        except GitProjectReaderError as error:
            raise VerificationRunnerError(
                "implementation_operation_evidence_invalid",
                "无法读取实施切片的调查基点或当前工作树",
                details=[str(error)],
            ) from error
        results: list[dict[str, Any]] = []
        for reference in self.operation_refs(slice_value):
            text = str(reference)
            index_text = (
                text[len("operations[") : -1]
                if text.startswith("operations[") and text.endswith("]")
                else ""
            )
            if not index_text.isdigit() or int(index_text) >= len(operations):
                continue
            operation = operations[int(index_text)]
            if not isinstance(operation, Mapping):
                continue
            if "repository_id" in operation and operation["repository_id"] != current["data"].get("selected_repository_id"):
                continue
            action = str(operation.get("action") or "")
            path = str(operation.get("path") or "").replace("\\", "/")
            to_path = str(operation.get("to_path") or "").replace("\\", "/")
            base_exists = base_reader.exists(path)
            current_exists = current_reader.exists(path)
            realized = False
            if action == "create":
                realized = not base_exists and current_exists
            elif action == "delete":
                realized = base_exists and not current_exists
            elif action == "move":
                realized = (
                    base_exists
                    and not current_exists
                    and bool(to_path)
                    and current_reader.exists(to_path)
                )
            elif action == "modify" and base_exists and current_exists:
                try:
                    realized = base_reader.read_canonical_bytes(
                        path,
                        "实施前文件",
                    ) != current_reader.read_canonical_bytes(
                        path,
                        "实施后文件",
                    )
                except GitProjectReaderError as error:
                    raise VerificationRunnerError(
                        "implementation_operation_evidence_invalid",
                        "无法比较实施操作前后的规范文件字节",
                        details={"operation_ref": text, "error": str(error)},
                    ) from error
            results.append(
                {
                    "operation_ref": text,
                    **({"repository_id": operation["repository_id"]} if "repository_id" in operation else {}),
                    "action": action,
                    "path": path,
                    "to_path": to_path or None,
                    "realized": realized,
                }
            )
        return results

    def require_operations_realized(
        self,
        current: Mapping[str, Any],
        plan: Mapping[str, Any],
        slice_value: Mapping[str, Any],
        *,
        observed_ref: str | None = None,
    ) -> list[dict[str, Any]]:
        results = self.operation_realization(
            current,
            plan,
            slice_value,
            observed_ref=observed_ref,
        )
        unrealized = [
            result["operation_ref"]
            for result in results
            if result["realized"] is not True
        ]
        if unrealized:
            raise VerificationRunnerError(
                "implementation_slice_operations_unrealized",
                "实施切片不能用摘要或验证回执冒充未形成的计划文件操作",
                details={
                    "slice_id": slice_value.get("slice_id"),
                    "unrealized_operation_refs": unrealized,
                    "operation_results": results,
                },
            )
        return results

    def path_snapshot(
        self,
        paths: Sequence[str],
        *,
        observed_ref: str | None = None,
    ) -> list[dict[str, str]]:
        reader = GitProjectReader(self.project, observed_ref=observed_ref)
        snapshot: list[dict[str, str]] = []
        existing = [path for path in sorted(set(paths)) if reader.exists(path)]
        try:
            contents = dict(reader.iter_canonical_files(existing, "实施切片完成证据"))
        except GitProjectReaderError as error:
            raise VerificationRunnerError("implementation_slice_snapshot_invalid", "无法形成实施切片文件的稳定完成证据", details=[str(error)]) from error
        for path in sorted(set(paths)):
            if path not in contents:
                snapshot.append({"path": path, "state": "absent", "sha256": ""})
                continue
            content = contents[path]
            snapshot.append(
                {
                    "path": path,
                    "state": "file",
                    "sha256": hashlib.sha256(content).hexdigest(),
                }
            )
        return snapshot

    def require_completed_slice_snapshots(
        self,
        current: Mapping[str, Any],
        *,
        observed_ref: str | None = None,
        exclude_paths: Sequence[str] = (),
    ) -> None:
        data = current.get("data")
        engineering = data.get("engineering") if isinstance(data, Mapping) else None
        plan = engineering.get("plan") if isinstance(engineering, Mapping) else None
        completions = (
            data.get("implementation_slice_completions")
            if isinstance(data, Mapping)
            else []
        )
        if (
            not isinstance(plan, Mapping)
            or not isinstance(completions, list)
            or not completions
        ):
            return
        receipts = data.get("verifications") if isinstance(data, Mapping) else []
        current_slice = focused_slice(
            plan,
            receipts if isinstance(receipts, list) else [],
            completions,
        )
        active_paths = (
            set(self.operation_paths(plan, current_slice, repository_id=current["data"].get("selected_repository_id")))
            if isinstance(current_slice, Mapping)
            else set()
        )
        if observed_ref is not None:
            active_paths = set()
        excluded = {
            str(path).replace("\\", "/")
            for path in exclude_paths
            if str(path).strip()
        }
        try:
            baseline = ProjectEngineeringBaseline(self.project).locate()
            baseline_path = baseline.relative_to(self.project).as_posix() if baseline.is_relative_to(self.project) else ""
        except ProjectEngineeringBaselineError:
            baseline_path = ""
        if baseline_path:
            excluded.add(baseline_path)
        expected_by_path: dict[str, dict[str, str]] = {}
        slices_by_id = {
            str(value.get("slice_id") or ""): value
            for value in plan.get("implementation_slices") or []
            if isinstance(value, Mapping)
        }
        for completion in completions:
            if not isinstance(completion, Mapping):
                continue
            slice_id = str(completion.get("slice_id") or "")
            slice_value = slices_by_id.get(slice_id)
            if not isinstance(slice_value, Mapping):
                raise VerificationRunnerError(
                    "implementation_slice_snapshot_invalid",
                    "实施切片完成证据引用了当前方案中不存在的切片",
                    details={"slice_id": slice_id},
                )
            realized = self.require_operations_realized(
                current,
                plan,
                slice_value,
                observed_ref=observed_ref,
            )
            expected_results = [value for value in completion.get("operation_results") or [] if "repository_id" not in value or value["repository_id"] == current["data"].get("selected_repository_id")]
            if expected_results != realized:
                raise VerificationRunnerError(
                    "implementation_slice_operation_evidence_stale",
                    "实施切片完成记录与当前计划操作的真实结果不一致",
                    details={"slice_id": slice_id},
                )
            raw_snapshot = completion.get("owned_path_snapshot")
            if not isinstance(raw_snapshot, list):
                raise VerificationRunnerError(
                    "implementation_slice_snapshot_missing",
                    "已完成实施切片缺少不可变文件快照；必须重新规划并重新形成证据",
                    details={"slice_id": completion.get("slice_id")},
                )
            for entry in raw_snapshot:
                if "repository_id" in entry and entry["repository_id"] != current["data"].get("selected_repository_id"):
                    continue
                if isinstance(entry, Mapping) and str(entry.get("path") or ""):
                    expected_by_path[str(entry["path"])] = {
                        "path": str(entry["path"]),
                        "state": str(entry.get("state") or ""),
                        "sha256": str(entry.get("sha256") or ""),
                    }
        protected_paths = sorted(set(expected_by_path) - active_paths - excluded)
        actual = {
            entry["path"]: entry
            for entry in self.path_snapshot(
                protected_paths,
                observed_ref=observed_ref,
            )
        }
        changed = [
            path
            for path in protected_paths
            if actual.get(path) != expected_by_path[path]
        ]
        if changed:
            raise VerificationRunnerError(
                "implementation_slice_evidence_stale",
                "后续工作改写了已完成切片且未声明延续所有权；旧验证或完成证据已经失效",
                details={
                    "changed_paths": changed,
                    "current_slice_id": (
                        current_slice.get("slice_id")
                        if isinstance(current_slice, Mapping)
                        else None
                    ),
                },
            )

    def candidate_snapshot(
        self,
        current: Mapping[str, Any],
    ) -> dict[str, Any] | None:
        """Bind one actual result to the exact final slice-controlled files."""

        data = current.get("data")
        engineering = data.get("engineering") if isinstance(data, Mapping) else None
        plan = engineering.get("plan") if isinstance(engineering, Mapping) else None
        if not isinstance(plan, Mapping) or not plan.get("implementation_slices"):
            return None
        receipts = data.get("verifications") if isinstance(data, Mapping) else []
        completions = (
            data.get("implementation_slice_completions")
            if isinstance(data, Mapping)
            else []
        )
        reportability = implementation_slice_reportability(
            plan,
            receipts if isinstance(receipts, list) else [],
            completions if isinstance(completions, list) else [],
        )
        if not reportability.get("reportable"):
            raise VerificationRunnerError(
                "implementation_slices_incomplete",
                "尚不能形成实施结果文件快照",
            )
        not_executed = set(reportability.get("not_executed_slice_ids") or [])
        included_slices = [
            value
            for value in plan.get("implementation_slices") or []
            if isinstance(value, Mapping)
            and str(value.get("slice_id") or "") not in not_executed
        ]
        paths = sorted(
            {
                path
                for slice_value in included_slices
                for path in self.operation_paths(plan, slice_value, repository_id=current["data"].get("selected_repository_id"))
            }
        )
        work_area = self._work_area(current)
        workspace = GitWorkspace(str(work_area["repository"]))
        comparison_base_commit = str(work_area.get("base_commit") or "")
        if work_area.get("conflict_resolution") or (work_area.get("integration") or {}).get("outcome") == "conflict":
            comparison_base_commit = workspace.resolve_commit("HEAD")
            changed_paths = workspace.changed_worktree_paths_from(
                comparison_base_commit
            )
        else:
            changed_paths = workspace.changed_paths(dict(work_area))
        return {
            "schema_version": IMPLEMENTATION_CANDIDATE_SNAPSHOT_SCHEMA,
            "repository_id": current["data"].get("selected_repository_id"),
            "plan_id": str(plan.get("plan_id") or ""),
            "base_commit": str(work_area.get("base_commit") or ""),
            "comparison_base_commit": comparison_base_commit,
            "included_slice_ids": [
                str(value["slice_id"]) for value in included_slices
            ],
            "terminal_slice_id": reportability.get("terminal_slice_id"),
            "not_executed_slice_ids": sorted(not_executed),
            "changed_paths": changed_paths,
            "paths": self.path_snapshot(paths),
            "semantic_content_machine_proven": False,
        }

    def conflict_candidate_snapshot(
        self,
        current: Mapping[str, Any],
    ) -> dict[str, Any] | None:
        """Bind an unchanged conflict resolution to the accepted delivery."""

        data = current.get("data")
        actual_result = data.get("actual_result") if isinstance(data, Mapping) else None
        accepted_snapshot = (
            actual_result.get("implementation_candidate_snapshot")
            if isinstance(actual_result, Mapping)
            else None
        )
        if isinstance(accepted_snapshot, Mapping) and accepted_snapshot.get("schema_version") == "strixnova.project-implementation-snapshot.v1":
            accepted_snapshot = next((entry for entry in accepted_snapshot["repositories"] if entry["repository_id"] == current["data"].get("selected_repository_id")), None)
        if not isinstance(accepted_snapshot, Mapping) or not isinstance(
            accepted_snapshot.get("paths"), list
        ):
            return None
        git = data.get("git") if isinstance(data, Mapping) else None
        resolution = (
            git.get("conflict_resolution") if isinstance(git, Mapping) else None
        )
        integration = git.get("integration") if isinstance(git, Mapping) else None
        conflict_entries = (
            resolution.get("conflict_entries")
            if isinstance(resolution, Mapping)
            else integration.get("conflict_entries")
            if isinstance(integration, Mapping)
            else []
        )
        conflict_paths = {
            str(entry)[3:].replace("\\", "/")
            for entry in conflict_entries or []
            if len(str(entry)) >= 4
            and ("U" in str(entry)[:2] or str(entry)[:2] in {"AA", "DD"})
        }
        accepted_by_path = {
            str(entry.get("path") or ""): dict(entry)
            for entry in accepted_snapshot["paths"]
            if isinstance(entry, Mapping)
            and str(entry.get("path") or "").strip()
        }
        unexpected_conflicts = sorted(conflict_paths - set(accepted_by_path))
        if unexpected_conflicts:
            raise VerificationRunnerError(
                "conflict_path_unplanned",
                "原生合入冲突包含负责人未确认的交付路径；必须重新规划",
                details=unexpected_conflicts,
            )
        non_conflict_paths = sorted(set(accepted_by_path) - conflict_paths)
        current_non_conflict = {
            entry["path"]: entry
            for entry in self.path_snapshot(non_conflict_paths)
        }
        changed_non_conflict = sorted(
            path
            for path in non_conflict_paths
            if current_non_conflict.get(path) != accepted_by_path[path]
        )
        if changed_non_conflict:
            raise VerificationRunnerError(
                "non_conflict_delivery_path_changed",
                "冲突解决改写了未发生原生冲突的已确认交付文件；不能扩大复测快照范围",
                details=changed_non_conflict,
            )
        replacement = {
            entry["path"]: entry
            for entry in self.path_snapshot(sorted(conflict_paths))
        }
        workspace = GitWorkspace(self.project)
        comparison_base_commit = workspace.resolve_commit("HEAD")
        actual_conflict_paths = set(
            workspace.changed_worktree_paths_from(comparison_base_commit)
        )
        expected_conflict_paths = {
            str(path).replace("\\", "/")
            for path in accepted_snapshot.get("changed_paths") or []
            if str(path).strip()
        }
        unexpected_paths = sorted(actual_conflict_paths - expected_conflict_paths)
        missing_paths = sorted(expected_conflict_paths - actual_conflict_paths)
        current_missing = {
            entry["path"]: entry for entry in self.path_snapshot(missing_paths)
        }
        unproven_missing = sorted(
            path
            for path in missing_paths
            if current_missing.get(path) != accepted_by_path.get(path)
        )
        if unexpected_paths or unproven_missing:
            raise VerificationRunnerError(
                "conflict_delivery_path_set_changed",
                "冲突解决后的本事项路径集合包含夹带，或缺失路径无法证明已同内容收敛",
                details={
                    "expected_paths": sorted(expected_conflict_paths),
                    "actual_paths": sorted(actual_conflict_paths),
                    "unexpected_paths": unexpected_paths,
                    "unproven_missing_paths": unproven_missing,
                },
            )
        conflict_snapshot = deepcopy(dict(accepted_snapshot))
        conflict_snapshot["paths"] = [
            replacement.get(path, accepted_by_path[path])
            for path in sorted(accepted_by_path)
        ]
        conflict_snapshot["comparison_base_commit"] = comparison_base_commit
        conflict_snapshot["changed_paths"] = sorted(expected_conflict_paths)
        return conflict_snapshot

    def require_candidate_snapshot(
        self,
        current: Mapping[str, Any],
        *,
        observed_ref: str | None = None,
        comparison_base_ref: str | None = None,
        exclude_paths: Sequence[str] = (),
        use_conflict_resolution: bool = False,
    ) -> None:
        """Reject any file swap after the owner saw the actual result."""

        data = current.get("data")
        actual_result = data.get("actual_result") if isinstance(data, Mapping) else None
        engineering = data.get("engineering") if isinstance(data, Mapping) else None
        plan = engineering.get("plan") if isinstance(engineering, Mapping) else None
        if not isinstance(plan, Mapping) or not plan.get("implementation_slices"):
            return
        if use_conflict_resolution:
            git = data.get("git") if isinstance(data, Mapping) else None
            resolution = (
                git.get("conflict_resolution")
                if isinstance(git, Mapping)
                else None
            )
            snapshot = (
                resolution.get("implementation_candidate_snapshot")
                if isinstance(resolution, Mapping)
                else None
            )
        else:
            snapshot = (
                actual_result.get("implementation_candidate_snapshot")
                if isinstance(actual_result, Mapping)
                else None
            )
        if isinstance(snapshot, Mapping) and snapshot.get("schema_version") == "strixnova.project-implementation-snapshot.v1":
            snapshot = next((entry for entry in snapshot["repositories"] if entry["repository_id"] == current["data"].get("selected_repository_id")), None)
        if (
            not isinstance(snapshot, Mapping)
            or snapshot.get("schema_version")
            != IMPLEMENTATION_CANDIDATE_SNAPSHOT_SCHEMA
            or (snapshot.get("plan_id") != plan.get("plan_id") and snapshot != (data.get("git") or {}).get("integrated_content_snapshot"))
            or snapshot.get("semantic_content_machine_proven") is not False
            or not isinstance(snapshot.get("paths"), list)
            or not isinstance(snapshot.get("changed_paths"), list)
        ):
            raise VerificationRunnerError(
                "implementation_candidate_snapshot_missing",
                (
                    "冲突解决复测没有绑定当前目标工作树的完整实施文件快照"
                    if use_conflict_resolution
                    else "实际结果没有绑定当前方案的完整实施文件快照"
                ),
            )
        excluded = {
            str(path).replace("\\", "/")
            for path in exclude_paths
            if str(path).strip()
        }
        work_area = self._work_area(current)
        workspace = GitWorkspace(str(work_area["repository"]))
        base_commit = str(
            comparison_base_ref
            or snapshot.get("comparison_base_commit")
            or snapshot.get("base_commit")
            or ""
        )
        if observed_ref is None and (comparison_base_ref is not None or work_area.get("conflict_resolution")):
            actual_changed_paths = set(
                workspace.changed_worktree_paths_from(base_commit)
            )
        elif observed_ref is None:
            actual_changed_paths = set(workspace.changed_paths(dict(work_area)))
        else:
            actual_changed_paths = set(
                workspace.changed_paths_between(base_commit, observed_ref)
            )
        expected_changed_paths = {
            str(path).replace("\\", "/")
            for path in snapshot["changed_paths"]
            if str(path).strip()
        }
        missing_paths = sorted(
            (expected_changed_paths - excluded)
            - (actual_changed_paths - excluded)
        )
        unexpected_paths = sorted(
            (actual_changed_paths - excluded)
            - (expected_changed_paths - excluded)
        )
        converged_integration = comparison_base_ref is not None
        if unexpected_paths or (missing_paths and not converged_integration):
            raise VerificationRunnerError(
                "accepted_implementation_path_set_changed",
                "负责人确认后的完整交付路径集合发生了增删；不能夹带或遗漏文件",
                details={
                    "missing_paths": missing_paths,
                    "unexpected_paths": unexpected_paths,
                    "observed_ref": observed_ref or "working_tree",
                },
            )
        expected = {
            str(entry.get("path") or ""): dict(entry)
            for entry in snapshot["paths"]
            if isinstance(entry, Mapping)
            and str(entry.get("path") or "") not in excluded
        }
        actual = {
            entry["path"]: entry
            for entry in self.path_snapshot(
                sorted(expected),
                observed_ref=observed_ref,
            )
        }
        changed = sorted(
            path for path in expected if actual.get(path) != expected[path]
        )
        if changed:
            raise VerificationRunnerError(
                "accepted_implementation_candidate_changed",
                "负责人看到的实际结果文件在确认、提交或合入阶段发生了变化",
                details={
                    "changed_paths": changed,
                    "observed_ref": observed_ref or "working_tree",
                },
            )
        unproven_missing = sorted(path for path in missing_paths if path not in expected)
        if unproven_missing:
            raise VerificationRunnerError(
                "accepted_implementation_path_set_changed",
                "合入贡献中缺少的路径没有最终内容快照，不能证明为同内容收敛",
                details={
                    "missing_paths": unproven_missing,
                    "observed_ref": observed_ref,
                },
            )

    @staticmethod
    def mechanical_authority_paths(current: Mapping[str, Any]) -> list[str]:
        """Return only paths whose metadata was mechanically adopted."""

        data = current.get("data")
        adoption = data.get("authority_adoption") if isinstance(data, Mapping) else None
        if not isinstance(adoption, Mapping):
            return []
        identifier = data.get("selected_repository_id")
        if identifier is None:
            area = data.get("git") or {}
            recorded_root = area.get("repository")
            candidate_root = area.get("worktree_path") or recorded_root
            if candidate_root and not Path(candidate_root).is_dir():
                candidate_root = recorded_root
            if recorded_root and candidate_root:
                context = ProjectContextResolver(candidate_root).configured(use_execution_bindings=False)
                if context is not None:
                    native = GitProjectReader(recorded_root)
                    matches = [repository.repository_id for repository in context.repositories
                               if repository.membership == "member" and repository.scope is not None
                               and native.repository_scope(repository.repository_id).git_common_dir == repository.scope.git_common_dir]
                    if len(matches) == 1:
                        identifier = matches[0]
        paths = {str(adoption.get("baseline_path") or "").replace("\\", "/")} if adoption.get("baseline_repository_id") == identifier or "baseline_repository_id" not in adoption else set()
        paths.update(
            str(update.get("path") or "").replace("\\", "/")
            for update in adoption.get("authority_updates") or []
            if isinstance(update, Mapping) and ("repository_id" not in update or update["repository_id"] == identifier)
        )
        actual_result = data.get("actual_result")
        if isinstance(actual_result, Mapping):
            alignment_repository = (actual_result.get("authority_candidate_snapshot") or {}).get("authority_repositories", {}).get("implementation_alignment")
            paths.update(
                str(reference.get("path") or "").replace("\\", "/")
                for reference in actual_result.get("long_lived_refs") or []
                if isinstance(reference, Mapping)
                and reference.get("artifact_type") == "domain_alignment"
                and (alignment_repository == identifier or "authority_repositories" not in (actual_result.get("authority_candidate_snapshot") or {}))
            )
        return sorted(path for path in paths if path)


